    check("  it opens the bridge socket", socketAttempts.length === 1, socketAttempts.join());
    check("  pointed at the bridge URL", /ws:\/\/127\.0\.0\.1:\d+/.test(socketAttempts[0] || ""),
        socketAttempts[0]);
